import {REGIONS,ITEMS,WORLD} from './data.js';
import {DISTRICTS} from './district-data.js';
import {BMAPS} from './beyond-data.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const ATLAS_POINTS={farm:[160,350],market:[365,450],residential:[475,270],hospital:[660,400],warehouse:[665,170],valley:[145,200],stationMarket:[400,610],courtyard:[440,110],quarantine:[860,405],railDepot:[790,170],pinewood:[125,75],shipyard:[655,610],shelter:[675,285],frost:[895,70],archive:[890,610]};
export const ATLAS_ROUTES=[['farm','market'],['market','residential'],['residential','hospital'],['hospital','warehouse'],...Object.entries(DISTRICTS).map(([id,d])=>[d.parent,id]),...Object.entries(BMAPS).map(([id,d])=>[d.parent,id])];
export const regionOpen=(e,id)=>!!REGIONS[id]&&(DISTRICTS[id]?!!e.d.unlocked[id]:BMAPS[id]?!!e.b.unlocked[id]:true);
export function accessConditions(e,id){const row=(text,pass)=>({text,pass:!!pass});switch(id){
 case 'valley':return [row('收获过一株作物',e.s.stats.harvested>=1)];
 case 'stationMarket':return [row('出售过一次物品',e.s.stats.sold>=1)];
 case 'courtyard':return [row('接回阿禾',e.resident('farmer'))];
 case 'quarantine':return [row('医院前哨恢复至二级',e.r.outposts.hospital>=2)];
 case 'railDepot':return [row('接回陈工',e.resident('mechanic')),row('完成动力恢复研究',e.r.tech.power)];
 case 'pinewood':return [row('溪谷试验田已开放',e.d.unlocked.valley),row('接回阿禾',e.resident('farmer'))];
 case 'shipyard':return [row('旧站商街已开放',e.d.unlocked.stationMarket),row('修复旧桥',e.projectDone('bridge'))];
 case 'shelter':return [row('雨巷住区已开放',e.d.unlocked.courtyard),row('接回许医生',e.resident('medic')),row('医院前哨恢复至二级',e.r.outposts.hospital>=2)];
 case 'frost':{const count=['pinewood_coop','shipyard_ferry','shelter_air'].filter(p=>e.bflag(p,'service')).length;return [row('北线货运站已开放',e.d.unlocked.railDepot),row('接回陈工',e.resident('mechanic')),row('完成动力恢复研究',e.r.tech.power),row('恢复林业互助站、固定航线、主风道中的任意两项（'+count+'/2）',count>=2)];}
 case 'archive':return [row('完成旧城复兴主线',e.r.ended),row('恢复沉湾固定航线',e.bflag('shipyard_ferry','service')),row('在山顶测向台记录航向',e.bflag('frost_bearing','survey'))];
 default:return [];
}}
export function regionAccess(e,id){if(!REGIONS[id])return null;const d=DISTRICTS[id]||BMAPS[id],open=regionOpen(e,id),conditions=accessConditions(e,id),materials=Object.entries(d?.cost||{}).map(([item,n])=>({id:item,name:ITEMS[item].name,need:n,have:DISTRICTS[id]?e.districtAvailable(item,d.parent):e.bqty(item,d.parent)}));return {id,...REGIONS[id],parent:d?.parent,gate:d?.gate,cost:d?.cost||{},open,conditions,materials,ready:conditions.every(x=>x.pass),blocked:e.districtTravelReason(id),purpose:d?.purpose||REGIONS[id].res};}
export function gateDestination(e,id){const d=DISTRICTS[id]||BMAPS[id];if(!d)return null;if(!regionOpen(e,d.parent))return gateDestination(e,d.parent);return {region:d.parent,...d.gate,label:REGIONS[id].name+'入口',name:REGIONS[id].name+'入口',destination:id};}
const btn=(a,id,text,disabled=false)=>`<button data-action="${a}" data-id="${esc(id)}" ${disabled?'disabled':''}>${esc(text)}</button>`;
export function localLandmarks(e){const types=['home','well','sign','allianceCamp','allianceSite','allianceNeighbors','trader','rescue','pond','districtPoint','districtGate','districtStore','districtExit','beyondPoint','beyondGate','beyondStore','beyondExit'];const target=e.guidance?.target;const list=(e.objects||[]).filter(o=>types.includes(o.type)&&o.name).map(o=>({x:o.x,y:o.y,label:o.name,target:false}));if(target?.region===e.s.region){const near=list.find(o=>Math.hypot(o.x-target.x,o.y-target.y)<35);if(near){near.label=target.label||target.name;near.target=true;}else list.push({...target,label:target.label||target.name,target:true});}return list;}
export function renderAtlas(e,ui={}){const selected=REGIONS[ui.selected]?ui.selected:e.s.region,local=ui.tab==='local',d=regionAccess(e,selected);return `<div class="atlas-layout"><header class="atlas-toolbar"><div role="group" aria-label="地图范围">${btn('aTab','world','世界地图')}${btn('aTab','local','本地区')}</div><label>定位地区<select id="atlas-region" aria-label="定位地区">${Object.keys(ATLAS_POINTS).map(id=>`<option value="${id}" ${id===selected?'selected':''}>${REGIONS[id].name}${regionOpen(e,id)?'':' · 未开放'}</option>`).join('')}</select></label><span>当前位置 · ${REGIONS[e.s.region].name}</span></header>${local?`<div class="atlas-local"><p>当前地区 · ${REGIONS[e.s.region].name}　拖动或滚动查看地标</p><div class="atlas-local-map"><canvas id="region-preview" class="region-preview" aria-label="${REGIONS[e.s.region].name}本地地图"></canvas>${localLandmarks(e).map(p=>`<span class="atlas-landmark ${p.target?'target':''}" style="left:${Math.max(8,Math.min(92,p.x/WORLD.w*100))}%;top:${Math.max(7,Math.min(93,p.y/WORLD.h*100))}%"><i></i>${esc(p.label)}</span>`).join('')}</div><p>白色：你　金色：目标或补给　青色：地点　红色：危险</p>${e.s.grave?.region===e.s.region?'<p>遗落的背包仍在本地区，可返回取回。</p>':''}</div>`:`<div class="atlas-main"><div class="atlas-scroll" tabindex="0" aria-label="地区地图，可横向滚动"><div class="atlas-land"><svg viewBox="0 0 1000 700" aria-hidden="true" class="atlas-terrain"><defs><pattern id="atlas-grid" width="50" height="50" patternUnits="userSpaceOnUse"><path d="M50 0H0V50" fill="none" stroke="#a4b298" stroke-opacity=".1"/></pattern><pattern id="atlas-water" width="30" height="20" patternUnits="userSpaceOnUse"><path d="M4 10h12M20 3h7" stroke="#b4d4c2" opacity=".2"/></pattern></defs><rect width="1000" height="700" fill="#263d32"/><path d="M0 20L70 0H430L470 62L440 150L330 205L290 325L165 390L0 352Z" fill="#344e38"/><path d="M570 0H1000V180L910 155L850 190L740 145L650 120Z" fill="#637469"/><path d="M710 0l48 42 30-20 43 53 37-41 43 17 32-42M780 14l25 32 24-12 43 40" fill="none" stroke="#a6b6a2" stroke-width="8" opacity=".5"/><path d="M0 575L170 565L255 530L335 563L440 533L580 580L700 529L755 540L820 479L1000 470V700H0Z" fill="#365e60"/><path d="M0 575L170 565L255 530L335 563L440 533L580 580L700 529L755 540L820 479L1000 470" fill="none" stroke="#98aaa0" stroke-opacity=".35" stroke-width="9"/><path d="M250 140L290 225L265 320L325 360L340 465L415 545" fill="none" stroke="#608b82" stroke-width="17"/><rect y="550" width="1000" height="150" fill="url(#atlas-water)"/><path d="M810 570l55-45 78 18 35 70-57 49-83-19Z" fill="#647957"/><path d="M550 563l80-15 70 25 15 67-155 13Z" fill="#657664"/><rect width="1000" height="700" fill="url(#atlas-grid)"/>${Array.from({length:20},(_,i)=>{const x=45+(i%5)*43,y=240+Math.floor(i/5)*34;return `<path d="M${x} ${y-15}l-10 17h6l-9 13h26l-9-13h6Z" fill="#496648" opacity=".8"/>`;}).join('')}${ATLAS_ROUTES.map(([a,b])=>{const [x,y]=ATLAS_POINTS[a],[xx,yy]=ATLAS_POINTS[b],open=regionOpen(e,b);return `<path d="M${x} ${y} Q${x} ${yy} ${xx} ${yy}" fill="none" stroke="${open?'#c3b68d':'#809384'}" stroke-width="${b===selected?5:3}" stroke-dasharray="${open?'0':'8 8'}" opacity="${open ? .85 : .65}"/>`;}).join('')}<text x="28" y="32" fill="#a8bda3" font-size="14" letter-spacing="5">余烬地区</text><path d="M967 28v38m-6-26 6-12 6 12" stroke="#b6c2a5" fill="none"/><text x="961" y="83" fill="#b6c2a5" font-size="13">北</text><text x="24" y="677" fill="#adc1b0" font-size="12">实线：通路开放　虚线：尚待开通</text></svg>${Object.entries(ATLAS_POINTS).map(([id,[x,y]])=>{const open=regionOpen(e,id),current=e.s.region===id;return `<button class="atlas-node ${open?'open':'locked'} ${id===selected?'selected':''} ${current?'here':''}" style="left:${x/10}%;top:${y/7}%" data-action="aSelect" data-id="${id}" aria-pressed="${id===selected}" aria-label="${REGIONS[id].name}，${current?'当前位置':open?'已开放':'未开放'}"><span class="atlas-symbol" aria-hidden="true">${current?'◆':open?'◇':'▣'}</span><strong>${REGIONS[id].name}</strong><small>${current?'你在这里':open?'可前往':'未开放'}</small></button>`;}).join('')}</div></div><aside class="atlas-info" aria-label="所选地区" aria-live="polite"><span class="atlas-status">${d.open?'通路已开放':'尚未开放'}</span><h3>${d.name}</h3><p>${esc(d.purpose)}</p>${!d.open?`<h4>开启条件</h4><ul class="atlas-conditions">${d.conditions.map(x=>`<li class="${x.pass?'met':''}"><span>${x.pass?'✓':'○'}</span>${esc(x.text)}</li>`).join('')}<li><span>○</span>到${REGIONS[d.parent].name}修复入口</li></ul><h4>修路材料</h4><p class="atlas-materials">${d.materials.map(x=>`<span class="${x.have>=x.need?'met':''}">${x.name} ${Math.min(x.have,x.need)}/${x.need}</span>`).join('')}</p><small>计入随身物资与入口所在地仓库。</small>`:`<p class="atlas-risk">${esc(d.risk)}</p>${e.s.region!==selected?'<small>出发消耗体力5、饥饿2；路上会推进游戏时间。</small>':''}`}<div class="atlas-primary">${d.open?btn('aTravel',selected,e.s.region===selected?'当前位置':'前往这里',e.s.region===selected||!!d.blocked):btn('aGate',selected,'标记入口所在位置')}${!d.open&&d.parent?btn('aSelect',d.parent,'查看'+REGIONS[d.parent].name):''}</div>${d.open&&d.blocked&&e.s.region!==selected?`<p class="atlas-blocked">${esc(d.blocked)}</p>`:''}${e.s.grave?.region===selected?'<p class="atlas-blocked">遗落的背包在这里。</p>':''}<small class="atlas-note">选择地名查看通路。设施工作在现场交互。</small></aside></div>`}</div>`;}
export function handleAtlasAction(action,el,ctx){if(!['aTab','aSelect','aTravel','aGate'].includes(action))return false;const {engine:e,ui,showMenu,closeMenu,renderMenu,save,toast}=ctx,id=el.dataset.id;if(action==='aTab'){ui.tab=id;renderMenu();return true;}if(!REGIONS[id])return true;if(action==='aSelect'){ui.selected=id;ui.tab='world';renderMenu();return true;}if(action==='aTravel'){if(e.travel(id)){closeMenu();save();}else renderMenu();return true;}const target=gateDestination(e,id);if(target){e.guidance.target=target;e.guidance.focus='gate:'+id;e.d.track=null;e.b.track=null;ctx.rebuildUI.target=target;if(e.s.region===target.region){closeMenu();toast('入口已标记，走到路标旁按 E 查看修路材料。');}else{ui.selected=target.region;ui.tab='world';renderMenu();toast('入口位于'+REGIONS[target.region].name+'，先前往这个地区。');}save();}return true;}
